  final _name = TextEditingController();
  final _password = TextEditingController();
  String? _nameError;
  String? _passwordError;
  bool _isPublic = false;

  @override
  void initState() {
    super.initState();
    _name.addListener(() => setState(() {})); // live slug preview
  }

  @override
  void dispose() {
    _name.dispose();
    _password.dispose();
    super.dispose();
  }

