    setState(() {
      _nameError = nameError;
      _passwordError = passwordError;
    });
    if (nameError != null || passwordError != null) return;
    Navigator.of(
      context,
    ).pop((name: slug, password: [REDACTED:Sensitive Value], isPublic: _isPublic));
  }

